forms_list_responses.beforeRequest:
// Encoded as the original's URLSearchParams query sends it: spaces as +, and ! ' ( ) ~ escaped.
var formEncoded = (text) => encodeURIComponent(String(text)).replace(/[!'()~]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase()).replace(/%20/g, '+');
var pairs = Object.keys(request.query).map((key) => formEncoded(key) + '=' + formEncoded(request.query[key]));
if (pairs.length > 0) request.url = request.url + '?' + pairs.join('&');
request.query = {};
return request;
